--- /dev/null
+++ b/examples/canfigger_get_double_attrs.c
@@ -0,0 +1,35 @@
+/*
+ * Compilable example for canfigger_get_double_attrs().
+ * Config line: scale = factors, 1.0, 0.75, 2.5
+ */
+#include <stdio.h>
+#include <string.h>
+#include "canfigger.h"
+
+static void
+example(struct Canfigger *node)
+{
+//! [canfigger_get_double_attrs]
+  /* Check the value tag, then validate the count before using the array. */
+  if (node->value && strcmp(node->value, "factors") == 0)
+  {
+    double v[3];
+    if (canfigger_get_double_attrs(node, v, 3) == 3)
+    {
+      fprintf(stderr, "factors: %g %g %g\n", v[0], v[1], v[2]);
+    }
+  }
+//! [canfigger_get_double_attrs]
+}
+
+int
+main(void)
+{
+  struct Canfigger *list = canfigger_parse_file("scale.conf", ',');
+  if (list)
+  {
+    example(list);
+    canfigger_free_list(&list);
+  }
+  return 0;
+}
diff --git a/examples/canfigger_parse_color.c b/examples/canfigger_parse_color.c
new file mode 100644
index 0000000..6095b4f
--- /dev/null
+++ b/examples/canfigger_parse_color.c
@@ -0,0 +1,26 @@
+#include <stdint.h>
+#include <stdio.h>
+#include "canfigger.h"
+
+int
+main(void)
+{
+  //! [canfigger_parse_color]
+  /*
+   * Config file entries this example handles:
+   *   bg_hex  = #FF8000
+   *   bg_rgb  = rgb, 255, 128, 0
+   *   bg_rgba = rgba, 255, 128, 0, 128
+   */
+  struct Canfigger *list = canfigger_parse_file("colors.conf", ',');
+  while (list)
+  {
+    uint8_t r, g, b, a;
+    int n = canfigger_parse_color(list, &r, &g, &b, &a);
+    if (n >= 3)
+      fprintf(stderr, "%s: rgba(%u,%u,%u,%u)\n", list->key, r, g, b, a);
+    canfigger_free_current_key_node_advance(&list);
+  }
+  //! [canfigger_parse_color]
+  return 0;
+}
